nextflow_process {

    name "Test Process AMPS"
    script "../main.nf"
    process "AMPS"

    tag "modules"
    tag "modules_nfcore"
    tag "amps"
    tag "malt/build"
    tag "malt/run"
    tag "maltextract"

    config "./nextflow.config"

    test("maltextract - sarscov2 - genome_fasta") {
        def malt_db
        def ncbi_taxmap
        setup {
            malt_db = extract('s3://nf-core-test-datasets/modules/data/delete_me/malt/megan-nucl-Feb2022.db.zip')
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            ncbi_taxmap = extract(modules_testdata_base_path + 'genomics/sarscov2/genome/db/maltextract/ncbi_taxmap.zip')
            run("MALT_BUILD") {
                script "../../malt/build/main.nf"
                process {
                    """
                    input[0] = [
                        [id: "genome"],
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                    ]
                    input[1] = []
                    input[2] = file('${malt_db}')
                    input[3] = "-mapDB"
                    """
                }
            }
            run("MALT_RUN") {
                script "../../malt/run/main.nf"
                process {
                    """
                    input[0] = Channel.of([
                        [ id:'test', single_end:false ], // meta map
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                    ])
                    input[1] = MALT_BUILD.out.index
                    """
                }
            }
            run("MALTEXTRACT") {
                script "../../maltextract/main.nf"
                process {
                    """
                    input[0] = MALT_RUN.out.rma6
                    input[1] = file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/db/maltextract/taxon_list.txt', checkIfExists: true)
                    input[2] = file('${ncbi_taxmap}')
                    """
                }
            }
        }
        when {
            params {
                malt_run_args = "-m BlastN -J-Xmx8G"
                malt_build_args = "--sequenceType DNA"
                maltextract_args = "-f def_anc"
            }
            process {
                """
                input[0] = MALTEXTRACT.out.results.map { it[1] }
                input[1] = file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/db/maltextract/taxon_list.txt', checkIfExists: true)
                input[2] = false
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    process.out.findAll { key, val -> key.startsWith('versions') },
                    process.out.json,
                    process.out.tsv,
                    process.out.summary_pdf.collect{file(it).name},
                    process.out.candidate_pdfs.collect{file(it).listFiles().name}
                ).match() }
            )
        }

    }

    test("sarscov2 - stub") {

        options "-stub"

        when {
            params {
                malt_run_args = "-m BlastN -J-Xmx8G"
                malt_build_args = "--sequenceType DNA"
                malt_extract_args = "-f def_anc"
            }
            process {
                """
                input[0] = []
                input[1] = file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/db/maltextract/taxon_list.txt', checkIfExists: true)
                input[2] = false
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

}

process {
    withName: MALT_RUN {
        ext.args = {"${params.malt_run_args}"}
    }
    withName: MALT_BUILD {
        ext.args = {"${params.malt_build_args}"}
    }
    withName: MALTEXTRACT {
        ext.args = {"${params.maltextract_args}"}
    }
}
